import random

def solve_optimal(nums):
    total = 0
    for i in range(1, len(nums) - 1):
        if nums[i] > nums[i - 1] and nums[i] > nums[i + 1]:
            total += 1
    return total

def solve_brute(nums):
    return sum(1 for a, b, c in zip(nums, nums[1:], nums[2:]) if b > a and b > c)

def gen(rng, size):
    low, high = {"tiny": (1, 4), "small": (1, 12), "large": (30, 100)}[size]
    n = rng.randint(low, high)
    return [[rng.randint(0, 9) for _ in range(n)]]

def validate(args):
    return 1 <= len(args[0]) <= 10**5
